/**
 * Demonstrates how to list chat completions for a chat context.
 *
 * @summary List chat completions.
 */

import ModelClient from "@azure-rest/ai-inference";
import { type ModelClient as ModelClientType } from "@azure-rest/ai-inference";
import { DefaultAzureCredential } from "@azure/identity";
import { createSseStream } from "@azure/core-sse";
import { createRestError } from "@azure-rest/core-client";

// Load the .env file if it exists
import "dotenv/config";
import type { IncomingMessage } from "node:http";
import { AzureKeyCredential } from "@azure/core-auth";
// You will need to set these environment variables or edit the following values
const endpoint = process.env["ENDPOINT"] || "<endpoint>";
const key = process.env["KEY"];
const modelName = process.env["MODEL_NAME"];

export async function main(): Promise<void> {
  console.log("== Streaming Chat Completions Sample ==");

  const client = createModelClient();
  const response = await client
    .path("/chat/completions")
    .post({
      body: {
        messages: [
          { role: "system", content: "You are a helpful assistant. You will talk like a pirate." }, // System role not supported for some models
          { role: "user", content: "Can you help me?" },
          { role: "assistant", content: "Arrrr! Of course, me hearty! What can I do for ye?" },
          { role: "user", content: "What's the best way to train a parrot?" },
        ],
        stream: true,
        max_tokens: 128,
        model: modelName,
      },
    })
    .asNodeStream();

  if (!response.body) {
    throw new Error("The response body is undefined");
  }

  if (response.status !== "200") {
    const body = JSON.parse(await streamToString(response.body));
    throw createRestError({ ...response, body });
  }

  const sses = createSseStream(response.body as IncomingMessage);

  for await (const event of sses) {
    if (event.data === "[DONE]") {
      return;
    }
    for (const choice of JSON.parse(event.data).choices) {
      console.log(choice.delta?.content ?? "");
    }
  }

  async function streamToString(streamToConvert: NodeJS.ReadableStream): Promise<string> {
    // lets have a ReadableStream as a stream variable
    const chunks = [];

    for await (const chunk of streamToConvert) {
      chunks.push(Buffer.from(chunk));
    }

    return Buffer.concat(chunks).toString("utf-8");
  }
}

/*
 * This function creates a model client.
 */
